  $auto=($spec['auto_apply']??false)===true&&$source['checked_at']&&!$preview['conflicts']&&$rows&&!array_filter($preview['rows'],fn($r)=>$r['fraction']==='');if($auto)wasteApply($pdo,$admin,$token,true,false,false);$pdo->prepare("UPDATE waste_sources SET last_error='' WHERE id=?")->execute([$id]);$results[]=['source_id'=>$id,'status'=>$auto?'PASS':'REVIEW','preview_token'=>$token,'conflicts'=>count($preview['conflicts'])];}catch(Throwable $e){$pdo->prepare('UPDATE waste_sources SET last_error=? WHERE id=?')->execute(['GSZ_CALENDAR_SYNC_FAILED',$id]);$results[]=['source_id'=>$id,'status'=>'BLOCKED','error'=>'GSZ_CALENDAR_SYNC_FAILED'];}
